  let specContent = fs.readFileSync(specPath, 'utf8');
  let changed = false;

  specContent = specContent.replace(linkRegex, (match, title, link) => {
    const [fileLink, hash] = link.split('#');
    if (!hash || !hash.startsWith('L')) return match;

    const targetFilePath = path.join(path.dirname(specPath), fileLink);
    if (!fs.existsSync(targetFilePath)) return match;

    const targetContent = fs.readFileSync(targetFilePath, 'utf8').split('\n');

    // Fuzzy search for title in the target file
    // First, strip anything in parentheses from the title to find the base title
    const baseTitle = title.replace(/\s*\(\[validated by.*?\)\s*$/, '').trim();

    const lineIndex = targetContent.findIndex(line => 
      line.includes(baseTitle) && (line.includes('it(') || line.includes('describe(') || line.includes('test('))
    );

    if (lineIndex !== -1) {
      const newLineNum = lineIndex + 1;
      const testLine = targetContent[lineIndex];
      const titleMatch = testLine.match(/(?:it|describe|test)\(['"](.+?)['"]/);
      if (titleMatch) {
        let fullTitle = titleMatch[1];
        // STRIP the ([validated by: ...]) part from the title
        fullTitle = fullTitle.replace(/\s*\(\[validated by: .*?\]\(.*?\)\)/, '');

        const newMatch = `[validated by: ${fullTitle}](${fileLink}#L${newLineNum})`;
        if (match !== newMatch) {
          changed = true;
          return newMatch;
        }
      }
    }
    return match;
  });

  if (changed) {
    fs.writeFileSync(specPath, specContent);
    console.log(`Updated names in ${specPath}`);
  }
}

